(205, 53, 'Display Backing Doble Cara', NULL, 'Venta por mayor y menor de Display Backing Curvo importados para ferias, stands y eventos en Lima y Provincias.', NULL, '<div style=\"text-align: center;\"><strong>&#160;&#160;Display Backing Curvo para Ferias y Eventos en Lima y Provincias</strong></div>\r\n<br />\r\nDisplay Wall Curvo y recto con impresiÃ³n, Backing portatil para Empresas, stands, eventos y ferias, Display Publicitario portatil impreso en alta resoluciÃ³n 1440 dpi, incluye maletin, reflectores, diseÃ±o y las grÃ¡ficas impresas.<br />\r\n<br />\r\nEstructura araÃ±a de aluminio de 3 cuerpos, incluyen maletÃ­n de cargo, 2 reflectores.<br />\r\n<br />\r\nMedida: 3.44 x 2.30 mts.<br />\r\n<br />\r\nIncluye: ImpresiÃ³n de grÃ¡ficas, Estructura Backdrop, paneles de respaldo de polyestireno blanco (3 para los paneles frontales y 2 para los laterales , 2 luces de halÃ³geno (luz amarilla), sistema de montaje magnÃ©tico, el maletÃ­n de carga llevado con mango retrÃ¡ctil y ruedas (estilo de equipaje).<br />\r\n<br />\r\n<strong>MEDIDAS DISPONIBLES:&#160;</strong><br />\r\n<br />\r\nMEDIDA: 3X3<br />\r\nImpresiÃ³n Grafica: 3.44 ancho X 2.30 alto<br />\r\n<br />\r\nMEDIDA: 4X3<br />\r\nImpresiÃ³n Grafica: 4.14 ancho X 2.30 alto<br />\r\n<br />\r\nMEDIDA: 5X3<br />\r\nImpresiÃ³n Grafica: 4.84 ancho X 2.30 alto<br />\r\n<br />\r\nMEDIDA: 6X3<br />\r\nImpresiÃ³n Grafica: 5.54 ancho X 2.30 alto<br />\r\n<br />\r\nHacemos envios a Lima y Provincia.', '1490828794.jpg', 'Venta de Backing Display - Display Backing Doble Cara', 'Venta de Backing Display Curvo para ferias y eventos en Lima y Provincias.\r\nServicio Incluye: Display + DiseÃ±o + Luces + Parlantes.', 'Backing Display Curvo para Ferias y Eventos, Venta de Display importados de primera calidad.', 'publish', 0, 1, 12, NULL, NULL, NULL),
(206, 53, 'Display Velcro', NULL, 'Venta de Display Porta Brochure Z en acrÃ­lico, envÃ­os en Lima y provincia.', NULL, '<div style=\"text-align: center;\"><strong>&#160;DISPLAY PORTA BROCHURE Z EN ACRILICO</strong></div>\r\n<br />\r\nDisplay de soporte plegable de exhibiciÃ³n con aspecto elegante, proporciona vista a 2 lados es un display muy prÃ¡ctico para mostrar revistas, catalogos, brochure y otras piezas publicitarias.<br />\r\n<br />\r\nEs ideal para uso en oficinas, recepciones y ferias. Incluye un maletin de aluminio para facilitar su traslado.<br />\r\n<br />\r\n<strong>Medida de imagen: </strong>A4: 21cm x 29.7 cm<br />\r\n<strong>Material: </strong>Aluminio y Acrilico<br />\r\n<strong>Color: </strong>Plateado<br />\r\n<strong>Peso:</strong> 5.2kg<br />\r\n<strong>Incluye:</strong> Maletin de aluminio para su protecciÃ³n y facil transporte.<br type=\"_moz\" />', '1490829613.jpg', 'Display Porta Brochure Z en Acrilico - Display Velcro', 'Venta de Display Porta Brochure Z en acrilico importados de excelente calidad. Hacemos envios a Lima y Provincia', 'Porta Brochure Z en acrilico, Display Portabrochure Z en acrilico envios a Lima y Provincia.', 'publish', 0, 1, 15, NULL, NULL, NULL);
