(232, 44, 'Caja de Luz en AcrÃ­lico ', NULL, 'Un modelo innovador , hecho en acrÃ­lico elegante y atractivo. ', NULL, '<div style=\"text-align: center;\"><strong>&#160;CAJA DE LUZ - LETRERO HECHO EN ACRILICO CON LUZ LED<br />\r\n</strong></div>\r\n<div style=\"text-align: left;\"><strong><br />\r\n</strong>Un producto diferente, para clientes que buscan destacar su marca con elegancia. Esto es lo que provee el acrÃ­lico al acompaÃ±arlo con la Luz Led.<strong><br type=\"_moz\" />\r\n</strong></div>\r\n<br />\r\nCaja de luz hecha 100% en acrilico con acabados en Vinil y luz led.&#160;<br />\r\n<br />\r\n<div style=\"text-align: center;\"><img src=\"http://www.artevisualgroup.com.pe/images/image/letreros-publicitarios/letrero-acrilico.jpg\" width=\"490\" height=\"380\" align=\"middle\" alt=\"\" /></div>', '1498945651.jpeg', 'Letreros Publicitarios - Caja de Luz en AcrÃ­lico en Lima', 'Un producto diferente, para clientes que buscan destacar su marca con elegancia. Esto es lo que provee el acrÃ­lico al acompaÃ±arlo con la Luz Led.', 'Caja de luz hecha 100% en acrÃ­lico con acabados en Vinil y luz led. ', 'publish', 0, 0, 30, NULL, NULL, NULL),
(233, 46, 'Letras en Durafont - Tipo Domo', NULL, 'Fabricantes de letrero en Durafont, acabados especiales en Dommo Ã³ Satinado. Este producto es fÃ¡cil de instalar y transportar, puesto que es liviano.', 'Nueva opciÃ³n para hacer letras, logos y letreros en alto relieve. Durafont es un poliestireno extruido, que se usa en otros paÃ­ses reemplazando a la madera por ser mas liviano, limpio, fÃ¡cil de pintar, en varios espesores y resistente a la lluvia y al sol.', '<div style=\"text-align: center;\">Letras en Durafont - Tipo Domo&#160;</div>\r\n<br />\r\nDurafont es un producto elaborado de poliestireno extruido.<br />\r\nCon nuestro sistema de corte al agua procesamos cortes precisos y diseÃ±os complejos en corto tiempo.<br />\r\n<br />\r\nDirigido principalmente para la industria grÃ¡fica y publicitaria generando un gran impacto visual en exteriores e interiores.<br />\r\n<br />\r\nTenemos 2 tipos de acabado:<br />\r\n<br />\r\n*Dommo (Brillante).<br />\r\n*Satinado Ã³ Mate.<br />\r\n<br />\r\n<div style=\"text-align: center;\"><img src=\"http://www.artevisualgroup.com.pe/images/image/letras-gigantes-lima/classic-mr-mrs-letter-set-unpainted.jpg\" width=\"786\" height=\"786\" align=\"middle\" alt=\"\" /></div>\r\n<br />\r\n<img src=\"http://www.artevisualgroup.com.pe/images/image/letras-gigantes-lima/41537191_235820257278418_5145149144460951552_n.jpg\" width=\"960\" height=\"960\" align=\"middle\" alt=\"\" /><br />\r\n<br type=\"_moz\" />\r\n<div style=\"text-align: center;\"><img src=\"http://www.artevisualgroup.com.pe/images/image/letras-gigantes-lima/68811560bf18968c4dd57d0c8847caef.jpg\" width=\"1880\" height=\"940\" align=\"middle\" alt=\"\" /></div>', '1518639908.jpg', 'Letras en Durafont - Tipo Domo en Lima', 'Fabricantes de letreros publicitarios para exterior e interior en Lima y Provincias. Letreros de alta duraciÃ³n en Lima y provincias.', 'Letras en Durafont, fabricantes de letreros exterior e interior en Lima', 'publish', 0, 0, 1, NULL, NULL, NULL),
(234, 46, 'Letras en Durafont - Tipo Mate', NULL, 'Letras Publicitarias livianas, fÃ¡cil de instalar y sobre todo de alta duraciÃ³n. Resistente al sol y el agua. Funciona perfectamente como atrayente de nuevos clientes. ', 'Durafont es un material Ãºnico en el PerÃº diseÃ±ado para la elaboraciÃ³n de logos y letreros con volumen para la industria publicitaria. Nueva opciÃ³n para hacer letras, logos y letreros en alto relieve. Durafont es un poliestireno extruido, que se usa en otros paÃ­ses reemplazando a la madera por ser mas liviano, limpio, fÃ¡cil de pintar, en varios espesores y resistente a la lluvia y al sol.', 'LETRAS PUBLICITARIAS DE ALTA DURACION EN DURAFONT<br />\r\n<br />\r\nEl Durafont se caracterisa por resistir el Sol, no se decolora! Resiste el agua y es muy facil de instalar puesto que no pesa.<br />\r\n<div style=\"text-align: center;\"><img src=\"http://www.artevisualgroup.com.pe/images/image/Letras-Durafont/durafont-03.jpg\" width=\"500\" height=\"281\" align=\"middle\" alt=\"\" /></div>\r\n<br />\r\n<div style=\"text-align: center;\"><img src=\"http://www.artevisualgroup.com.pe/images/image/Letras-Durafont/durafont-01.jpg\" width=\"500\" height=\"375\" align=\"middle\" alt=\"\" /></div>\r\n<br />\r\n<div style=\"text-align: center;\"><img src=\"http://www.artevisualgroup.com.pe/images/image/Letras-Durafont/durafont-02.jpg\" width=\"500\" height=\"375\" align=\"middle\" alt=\"\" /></div>\r\n<br />\r\n<br type=\"_moz\" />', '1518639801.jpg', 'Letras en Durafont - Tipo Mate', 'Somos fabricantes de letreros corporativos en Lima, usamos el Durafont de alta DuraciÃ³n con acabados dommo. Realizamos instalaciÃ³n en Lima y Provincias.', 'Letras 3d corporativas de alta duraciÃ³n, letreros corporativos en Arequipa, Piura, Huancayo, Lima y Provincias.', 'publish', 0, 0, 2, NULL, NULL, NULL),
