(265, 46, 'Letras Gigantes 3D', NULL, 'Somos Fabricantes de letras gigantes, utilizamos diversos materiales como el celtex, MDF, trupan, acrÃ­lico . Hacemos incrustaciones y acabados con luces, flourescentes Ã³ focos led. Hacemos enviÃ³ e instalaciÃ³n en Lima y Provincias.', 'Expresa todo lo que quieras en tu evento con tus Letras Gigantes , con ellas podrÃ¡s conformar las palabras con las que quieras identificar tu evento. Por ejemplo la inicial de tu pareja y la tuya, la palabra love o cualquier palabra que le de un sello especial a tu evento.', '<div style=\"text-align: center;\">LETRAS GIGANTES 3D EN LIMA Y PROVINCIAS</div>\r\n<br />\r\nFabricamos letras de gran tamaÃ±o para eventos corporativos de gran enbargadura. La calidad que le damos a cada letra es unica puesto que utilizamos materiales que hacen mucho mÃ¡s elegante tu evento.<br />\r\n<br />\r\nPuedes obtener letras en celtex, Trupan,acrilico con incrustaciones de Luz led Ã³ pintadas en gloss acrilico.<br />\r\n<br />\r\n<br />\r\n<div style=\"text-align: center;\"><img src=\"http://www.artevisualgroup.com.pe/images/image/letras-gigantes-lima/letras-gigantes-lima.jpg\" width=\"640\" height=\"478\" align=\"middle\" alt=\"\" /><br />\r\n<br />\r\n<img src=\"http://www.artevisualgroup.com.pe/images/image/letras-gigantes-lima/letras-MDF.jpg\" width=\"570\" height=\"428\" align=\"middle\" alt=\"\" /></div>\r\n<br type=\"_moz\" />\r\n<div style=\"text-align: center;\"><img src=\"http://www.artevisualgroup.com.pe/images/image/letras-gigantes-lima/letras-para-bodas.jpg\" align=\"middle\" alt=\"\" /></div>', '1518632719.jpg', 'Letras Gigantes 3D para Matrimonios, Eventos y Municipalidades', 'Fabricamos letras gigantes en Lima y provincias, utilizamos celtex, trupan, acrilico, aluminio con acabados especiales y luces led; hacemos envÃ­os en Lima.', 'Fabricantes en Lima Peru de Letras Gigantes, letras 3d de gran tamaÃ±o en Lima, Arequipa, Piura, Huancayo, Pucallpa, Huancavelica.', 'publish', 0, 0, 5, NULL, NULL, NULL),
(266, 44, 'Letreros Luminosos', NULL, 'Somos Fabricantes de letreros luminosos , con estructuras de fierro para mayor duraciÃ³n y flourescentes led. Los recubrimos con Lona Traslucida, vinilo ploteado y ImpresiÃ³n de alta calidad 1440 DPI.', NULL, '<div style=\"text-align: center;\"><strong>&#160;FABRICANTES DE LETREROS Y CAJAS LUMINOSAS</strong></div>\r\n<br />\r\nSomos fabricantes de letreros y cajas luminosas de calidad. Las estructuras que utilizamos son de fierro cuadrado, esto le dara estabilidad a los letreros; nuestros acabados son de calidad con lona traslucida y vinilo ploteado.<br />\r\n<br />\r\nHacemos instalaciones en Lima y provincias a precios economicos al por mayor.<br />\r\n<br />\r\n<div style=\"text-align: center;\"><img src=\"http://www.artevisualgroup.com.pe/images/image/letreros-publicitarios/letreros-luminoso-01.jpg\" width=\"751\" height=\"563\" align=\"middle\" alt=\"\" /></div>\r\n<div style=\"text-align: center;\"><img src=\"http://www.artevisualgroup.com.pe/images/image/letreros-publicitarios/letreros-luminoso-02.jpg\" width=\"878\" height=\"550\" align=\"middle\" alt=\"\" /></div>', '1518648382.jpg', 'Publicidad Exterior e Interior - Venta de Letreros Luminosos', 'Fabricamos letreros luminosos de calidad a bajos precios con Flourescentes led. Instalacion en Lima, Arequipa, Huancayo, trujillo, Piura, Cusco y mÃ¡s.', 'Fabricantes de letreros Luminosos en Lima Peru, cajas luminosas en Lima Peru de Calidad', 'publish', 0, 0, 25, NULL, NULL, NULL),
(267, 43, 'Vinilos para Oficinas', NULL, 'ImpresiÃ³n total o parcial de su oficina con toques ejecutivos. 100% de impresiÃ³n e instalaciÃ³n en Lima y Provincias.', NULL, '&#160;VINILOS PARA OFICINAS PERU<br />\r\n<br />\r\nRotulamos su oficina total Ã³ parcialmente segÃºn diseÃ±os enviados Ã³ de lo contrario diseÃ±amos un arte exclusivamente para ustedes.<br />\r\n<br />\r\nTodos nuestros productos son de calidad y con un buen asesoramiento.&#160;<br />\r\n<br />\r\n<img src=\"http://www.artevisualgroup.com.pe/images/Vinilos Oficinas Lima Peru.jpg\" width=\"468\" height=\"261\" alt=\"\" /><br />\r\n<img src=\"http://www.artevisualgroup.com.pe/images/Vinilos para Oficinas Peru.jpg\" alt=\"\" /><br type=\"_moz\" />', '1518832481.jpg', 'Vinilos para Oficinas de calidad en Lima Peru', 'Decoramos su oficina con vinilos de calidad, los viriles le darÃ¡n un toque especial a tu oficina. Hacemos las instalaciones en Lima y Provincias.', 'vinilos para oficinas, viniles de calidad para oficinas en Peru, viniles decorativos en Lima ', 'publish', 0, 0, 27, NULL, NULL, NULL);

