CREATE TABLE `servicios` (
  `id` bigint(20) NOT NULL,
  `title` varchar(220) NOT NULL,
  `slug` varchar(120) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `description` text NOT NULL,
  `content` text NOT NULL,
  `thumbnail` varchar(120) NOT NULL,
  `metatitle` varchar(220) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `metadescription` varchar(220) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `metakeywords` varchar(220) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `status` enum('publish','draft') CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `orden` int(4) DEFAULT 0,
  `user_id` int(1) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_general_ci;

--
-- Volcado de datos para la tabla `servicios`
--

INSERT INTO `servicios` (`id`, `title`, `slug`, `description`, `content`, `thumbnail`, `metatitle`, `metadescription`, `metakeywords`, `status`, `orden`, `user_id`, `created_at`, `updated_at`) VALUES
(3, 'comercializacion de Empresas', 'comercializacion-de-empresas', '<p>Podr&aacute; comprar sus art&iacute;&shy;culos publicitarios para merchandising con o sin logo. Incluir su logo es muy f&aacute;cil, solo tiene que enviarnos en formato digital el logo de su empresa para que podamos realizar la incorporaci&oacute;n del mismo en el art&iacute;&shy;culo publicitario que resulte de su inter&eacute;s. Lo esperamos, su pr&oacute;xima campa&ntilde;a de merchandising se encuentra en Arte Visual Group.</p>', '<div style=\"text-align: justify;\">&nbsp;</div>', '/storage/photos/1/servicios/1510673267.jpg', 'Productos Promocionales de Merchandising, Publicidad', 'Venta y Fabricacion de articulos publicitarios,productos publicitarios Lima,Fabricantes de merchandising,productos,ArtÃ­culos Promocionales Merchandising', '', 'publish', 87, 1, NULL, '2025-11-05 19:37:47'),
(4, 'Empaques', NULL, 'Las bolsas y cajas publicitarias es una de las muchas formas de hacerse publicidad y marketear su empresa. \r\n\r\nARTE VISUAL GROUP realiza un previo diseÃ±o con las dimensiones que requiera su empresa. Las bolsas publicitarias mayormente se imprimen en papel couchÃ© o papel bond mientras que las cajas publicitarias en cartulina duplex o cartulina foldcote.', '<div style=\"text-align: justify\">Fabricamos todo tipo de cajas o empaques personalizados con o sin impresiÃ³n, en cartÃ³n o papel cuchÃ©. Elaboramos y diseÃ±amos segÃºn su pedido cajas para gran variedad de artÃ­culos o productos, cajas para tortas, comida rÃ¡pida, pizzas ropa, juguetes, calzados, bolsos de papel o en material cuchÃ©, publicitarios con o sin estampado, cajas y estuches de regalo.</div>', '/storage/photos/1/servicios/1636204296.jpg', 'DiseÃ±o de Cajas Publicitarias en Lima, DecoraciÃ³n', 'Cajas a Medida para Tiendas,Publicite su empresa con Cajas Publicitarias con su Logo,Distintos TamaÃ±os,DiseÃ±o Personalizados,Embalaje,Cajas,Papel Couche', '', 'publish', 7, NULL, NULL, NULL),
(5, 'Bolsas Publicitarias', NULL, 'Fabricadas en polietileno de alta o baja densidad con asa parche e impresas hasta 08 colores, las convierten en un excelente medio publicitario que genera una alta recordaciÃ³n de su marca. Pueden ser biodegradables y amigables con el medio ambiente.', 'Bolsas Publicitarias En Notex Ecologico, tocuyo y taslan<br />\r\nBolsos tipo Morral , Bolsas, Cooler Lonchera, Delantal-Pechera<br />\r\nEcologicas, Biodegradables<br />\r\n100% Reciclables<br />\r\nPRODUCTOS: PUBLICITA TU MARCA EN HERMOSAS BOLSAS ECOLOGICAS CONFECCIONADAS EN NOTEX; YUTE, CAMBRELL, PUEDEN IR ESTAMPADAS CON UN LOGO A UNO O MAS<br />\r\nCOLORES.<br />\r\nFIDELIZA A TUS CLIENTES, REGALA A TUS AMIGOS, MARCA LA DIFERENCIA CON UN BOLSO DIFERENTE Y ELEGANTE.<br />\r\n<br />\r\nPEDIDOS AL POR MAYOR Y MENOR.  ENVIOS A PROVINCIA', '/storage/photos/1/servicios/1510669149.jpg', 'Bolsas Publicitarias en Lima con Serigrafia a Domicilio - Provincias', 'Bolsas Publicitarias Impresas con el Logo de tu Empresa al por Mayor y Mejor Precio del Mercado,Bolsas Plasticas,Ecologicas,Colores y Modelos,TamaÃ±os a Esco', '', 'publish', 61, NULL, NULL, NULL),
(6, 'FOLDERS Y SOBRES CORPORATIVOS', NULL, 'Proveemos de material corporativo a diferentes empresas ya sea Folders, Sobres, Hojas Membretadas etc. Â¿SabÃ­a que? el 80% de las ventas son mÃ¡s efectivas si utiliza material corporativo, esto hace que al entregar documentos como cotizaciones sea una forma de persuadir a su potencial cliente y lo ayuda a tomar un desiciÃ³n de compra mucho mÃ¡s rÃ¡pido.', 'Un folder es parte de la imagen de su empresa. Ideal para la presentaciÃ³n de sus documentos. Presente su empresa de una manera profesional con un folder que muestre sus productos o servicios.<br />\r\n<ul>\r\n    <li>Para hojas tamaÃ±o carta</li>\r\n    <li>Gratis barniz UV alto brillo (exterior del folder)</li>\r\n    <li>Con solapas y hendidura para insertar tarjeta de presentaciÃ³n</li>\r\n    <li>ImpresiÃ³n a todo color</li>\r\n    <li>Tiempo de embarque: 7 dÃ­as hÃ¡biles</li>\r\n    <li>Cartulina SBS 16 ptos.</li>\r\n    <li>Medidas (Cerrado): 23 x 30 cm.</li>\r\n    <li>ImpresiÃ³n a todo color en 1 cara (Exterior del folder)</li>\r\n</ul>', '/storage/photos/1/servicios/1426023194.jpg', 'Venta al por Mayor de Sobres, bolsas y folders - Papeles en Lima ', 'Impresion de Folders Corporativos,Full Color en Papel Couche,Con Logo de la Empresa,Descuentos al por Mayor,Precios Baratos,Galeria Grafica,Sobres de todo T', '', 'publish', 43, NULL, NULL, NULL),
(7, 'Impresion sobre Papel', NULL, 'Los folletos hacen que las informaciones importantes lleguen exactamente. Y ademÃ¡s, a buen precio. Con nuestras ofertas podrÃ¡ reunir las informaciones relativas a su empresa, a las ventas o a sus eventos en cÃ³modos y efectivos folletos a muy buen precio.', 'Los folletos son un medio econÃ³mico para hacer llegar su mensaje a sus clientes potenciales.<br />\r\n<br />\r\nCon un trÃ­ptico podrÃ¡ presentar sus productos o servicios de una manera profesional y ordenada. Tenemos el mejor precio en impresiÃ³n de trÃ­pticos.<br />\r\n<br />\r\nSeleccione a continuaciÃ³n el modelo de folleto que requiere para conocer las especificaciones y precios:', '/storage/photos/1/servicios/1510670860.jpg', 'Impresion Full Color de Folletos en Lima, Imprenta Offset', 'Ofrecemos Alta Calidad de Folletos Publicitarios,Excelente Calidad de ImpresiÃ³n,DiseÃ±o de Folletos Online,Imprenta Economica en Lima,A3,A4,Personalizado.', '', 'publish', 10, NULL, NULL, NULL),
(9, 'FLYERS O BROSHURES', NULL, 'Elaboramos todo tipo de folleto promocional en diferentes materiales y tamaÃ±os, ofrecemos gran calidad en color en impresiÃ³n Offset y LÃ¡ser asÃ­ como tiempo excelente tiempo de entrega, ahorre en costos al no pagar por el arte pues es GRATIS, le recordamos preguntar por nuestras promociones para empresas y particulares.  ', '&#160;', '/storage/photos/1/servicios/1425482870.jpg', 'Venta de flyer, afiches, brochures a domicilio en Lima, Delivery, Imprenta', 'Impresion a Full Color de Flyers Economicos en Lima,Calidad,Mejores Precios.Imprenta Online,Brochures Corporativos,Volantes,Tripticos,Envios a Domicilio', '', 'publish', 61, NULL, NULL, NULL),
(10, 'Imantado Publicitario', NULL, 'Los imanes publicitarios son ideales para promover su producto o servicio, son llamativos, prÃ¡cticos y la mejor de sus cualidades es que la mayorÃ­a de las personas los conserva.\r\n\r\nPor lo regular los imanes promocionales son colocados en lugares visibles, que le recordarÃ¡n a su cliente el producto o servicio que promociona el Iman.', '<ul>\r\n    <li>Publicidad en el refrigerador de sus clientes</li>\r\n    <li>Papel imantado, delgado, muy resistente</li>\r\n    <li>Se puede escribir y borrar sobre su superficie</li>\r\n    <li>Ideal para:</li>\r\n</ul>\r\nPizzerias y restaurantes con entrega a domicilio<br />\r\nFarmacias, carnicerÃ­as, pastelerÃ­as, veterinarias, etc.<br />\r\nServicio y reparaciÃ³n de electrodomÃ©sticos<br />\r\nCalendarios<br />\r\nMenÃºs<br />\r\nNÃºmeros de emergencia y telÃ©fonos de servicio', '/storage/photos/1/servicios/1510671132.jpg', 'Imanes Corporativos Publicitarios en Lima - Imantados Full Color', 'Personalizado para Empresas,ImpresiÃ³n de imanes publicitarios de diferentes formas con logo corporativo,Full Color en Vinilo,Empresas,Descuentos,Precios', '', 'publish', 40, NULL, NULL, NULL),
(11, 'Agendas Personalizadas 2018', NULL, 'Agendas publicitarias con tu logo\r\nAprovecha la imagen de una buena agenda promocional para tus regalos de empresa.\r\nDesarrollamos cada aÃ±o una nueva colecciÃ³n de agendas publicitarias con distintas opciones de tamaÃ±o, encuadernaciÃ³n y diseÃ±o para que puedas disponer de un regalo publicitario adecuado a tu marca,\r\nPuedes decidirte tanto por agendas dÃ­a-pÃ¡gina como por agendas semana-vista.\r\nEntra en nuestro catÃ¡logo y descubre la variedad de diseÃ±os para 2017. Elige el mÃ¡s apropiado para tu marca. Nosotros nos encargamos de que la impresiÃ³n de tu logo sea la mejor.', '&#160;', '/storage/photos/1/servicios/1510666511.jpg', 'Venta de Agendas 2018 Personalizadas Corporativas al por Mayor', 'Venta de Agendas 2018,Regalos de Empresas,Excelentes Precios al por mayor,Fabricantes de Agendas Publicitarias con Logo,DiseÃ±os Exclusivos,Fabrica de Agenda', '', 'publish', 82, NULL, NULL, NULL),
(15, 'IMPRESION DE LIBROS', NULL, '', '&#160;', '/storage/photos/1/servicios/1425681895.jpg', 'Impresion Offset y Empastados de Libros,Revistas,Boletines en Lima', 'Taller de Impresion de Libros a Color,Digital,Papel Couche,Bond,Impresion Economica de Libros,Tesis,Revistas,Costo de Impresion de Libros en Lima Peru', '', 'publish', 78, NULL, NULL, NULL),
(17, 'IMPRESION DE TRIPTICOS, DIPTICOS', NULL, 'Los dÃ­pticos hacen que las informaciones importantes lleguen exactamente. Y ademÃ¡s, a buen precio. Con nuestras ofertas podrÃ¡ reunir las informaciones relativas a su empresa, a las ventas o a sus eventos en cÃ³modos y efectivos dÃ­pticos a dos caras a muy buen precio.\r\n\r\nLos trÃ­pticos hacen que las informaciones importantes lleguen exactamente. Y ademÃ¡s, a buen precio. Con nuestras ofertas podrÃ¡ reunir las informaciones relativas a su empresa, a las ventas o a sus eventos en cÃ³modos y efectivos dÃ­pticos a dos caras a muy buen precio.', '&#160;', '/storage/photos/1/servicios/1426100232.jpg', 'Impresion de Tripticos Publicitarios A4,Economicos,Folletos Doblados,Envios ', 'Servicio de Impresion Digital de Dipticos y Tripticos,Offset,Imprenta en Galerias Wilson,Folletos Plegados Full Color,Necesitas imprimir un Triptico ?', '', 'publish', 62, NULL, NULL, NULL),
(21, 'Muebles personalizados o a Medida', NULL, 'Encuentre los Muebles personalizados o a Medida perfectas para su empresa y su proyecto.', 'Te ofrecemos cinco medidas personalizadas con tu diseÃ±o y encuadernadas en wire-o. Para todos ellos tienes diferente opciones de configuraciÃ³n. Hablemos un poco sobre ellas.<br />\r\n<br />\r\n<strong>Tipo de impresiÃ³n</strong><br />\r\nNo hay opciÃ³n para la portada porque se imprime siempre a todo color. Recuerda que tu archivo tiene que cumplir con los requisitos imprescindibles para una imprenta. Pero de esto hablaremos un poco mÃ¡s adelante<br />\r\n<br />\r\n<strong>Hojas interiores</strong><br />\r\nEn la ficha de producto te vas a encontrar con 3 alternativas: A todo color a una cara, rayas o cuadrÃ­culas y dejar en blanco las pÃ¡ginas.<br />\r\n<br />\r\n<strong>Todo color a una cara<br />\r\n</strong>Puedes hacer el diseÃ±o personalizado como quieras y conseguir unas libretas originales, pero recuerda que ese diseÃ±o es el que se reproducirÃ¡ en todas sus hojas. Es decir, cada hoja irÃ¡ impresa con un mismo motivo por una pÃ¡gina y por la otra irÃ¡ sin impresiÃ³n de ningÃºn tipo. Hay gente que se lÃ­a un poco con la diferencia entre hoja y pÃ¡gina. Recuerda que una hoja tiene 2 pÃ¡ginas.<br />\r\n<br />\r\nUno de sus usos es como cuadernos corporativos en los que cada hoja lleva impresa su logotipo y sus datos de contacto. Un ejemplo real es el de unas empresas que patrocinan cada aÃ±o unas rutas culturales para escolares e imprimen unos cuadernos para los niÃ±os con una portada muy llamativa y con las hojas a color, como si fuesen blocs de viaje o libretas de campo, al mÃ¡s puro estilo del inolvidable FÃ©lix RodrÃ­guez de la Fuente.<br />\r\n<br />\r\n<strong>CuadrÃ­culas o lÃ­neas</strong><br />\r\nLas imprimimos en un gris suave para que lo que destaque sea lo que se escriba. Hay clientes que prefieren las libretas decoradas solamente en la portada y que en su interior figuren sÃ³lo las clÃ¡sicas rayas o cuadrÃ­culas. En este supuesto siempre recomendamos repasar muy bien el diseÃ±o de la tapa para no dejar olvidado por descuido cualquier dato que quieras que figure en ella.<br />\r\n<br />\r\nPara imprimir este tipo sÃ³lo tendrÃ¡s que enviarnos el diseÃ±o de las portadas. Es importante que nos digas si prefieres los cuadros o las rayas, algo que podrÃ¡s hacer en un campo de texto que se te habilitarÃ¡ al terminar de configurar el producto.<br />\r\n<br />\r\n<strong>Hojas en blanco</strong><br />\r\nMinimalismo en estado puro. Portada a todo color y todas las pÃ¡ginas sin imprimir. Por supuesto, son los mÃ¡s baratos. Utilizados mÃ¡s para dibujar que como cuaderno de notas.<br />\r\n<br />\r\n<strong>NÃºmero de hojas</strong><br />\r\nÃ‰sta es la segunda opciÃ³n que deberÃ¡s configurar para que te aparezcan los precios: 50 Ã³ 100 hojas, es decir, 100 Ã³ 200 pÃ¡ginas. Todos los tipos de los que acabamos de hablar admiten cualquiera de estas dos alternativas.', '/storage/photos/1/servicios/1636204257.jpg', 'Muebles personalizados o a Medida en Lima, Baratos - Alta Calidad', 'Convierta su logotipo o diseÃ±o en una etiqueta adhesiva fÃ¡cil de usar para colocar en su correspondencia, paquetes y mucho mÃ¡s.', '', 'publish', 6, NULL, NULL, NULL),
(22, 'Esculturas, Dummies, Ruletas y Corporeos Tematicos', NULL, 'Arte Visual Group te ofrece la posibilidad de pedir etiquetas, adhesivos y pegatinas con todas las especificaciones deseadas, a un precio inmejorable y con un tiempo de entrega rÃ©cord. Es posible elegir entre los materiales mÃ¡s valorados que se pueden encontrar en el mercado; desde el PVC adhesivo, blanco o transparente, a los numerosos tipos de papel, adhesivo o no adhesivo, acompaÃ±ados por una calidad de impresiÃ³n impecable, como en todos nuestros productos.', 'Etiquetas adhesivas personalizadas<br />\r\nLas modernÃ­simas tecnologÃ­as adoptadas por Pixartprinting permiten fabricar esplÃ©ndidas etiquetas adhesivas y etiquetas personalizadas, de cualquier forma y material.<br />\r\n<br />\r\nLa amplia personalizaciÃ³n de las etiquetas adhesivas Pixartprinting va desde el material (PVC, papeles Fasson, papeles satinados) hasta los acabados, como por ejemplo el tratamiento antirralladuras.<br />\r\n<br />\r\nLa impresiÃ³n digital de etiquetas y etiquetas personalizadas ofrecida por Pixartprinting, gracias a la experiencia en el sector de la impresiÃ³n digital, logra unir una enorme calidad del producto con una elevada competitividad en cuanto al precio.<br />\r\n<br />\r\nPixartprinting te ofrece la posibilidad de pedir etiquetas, adhesivos y pegatinas con todas las especificaciones deseadas, a un precio inmejorable y con un tiempo de entrega rÃ©cord. Es posible elegir entre los materiales mÃ¡s valorados que se pueden encontrar en el mercado; desde el PVC adhesivo, blanco o transparente, a los numerosos tipos de papel, adhesivo o no adhesivo, acompaÃ±ados por una calidad de impresiÃ³n impecable, como en todos nuestros productos.<br />\r\n<br />\r\nLa tecnologÃ­a empleada para la impresiÃ³n y la calidad de los materiales garantizan etiquetas adhesivas personalizadas de la mÃ¡s alta calidad, gracias tambiÃ©n a los numerosos efectos disponibles (efecto estuco, marfil, abedul, yeso, etc.)<br />\r\n<br /